function sceneCapabilities(item,applications){
 if(item.id==='crop_research')return '<span class="scene-capabilities"><small>时序观察</small><small>样本与核查</small></span>';
 const tools=item.tools.map(id=>applications.find(a=>a.id===id)).filter(Boolean),labels=['台账'];
 if(tools.some(a=>a.method?.index_id||a.method?.processing_family||a.method?.processing_algorithm_id))labels.push('影像分析');
 else if(tools.some(a=>a.scope==='archived_raster'))labels.push('栅格分析');
 else if(tools.some(a=>['cropland_delineation','land_resources'].includes(a.id)))labels.push('年度参考');
 else if(tools.some(a=>a.id==='imagery_search'))labels.push('影像查询');
 else if(tools.some(a=>a.id==='weather'))labels.push('天气参考');
 return `<span class="scene-capabilities">${labels.map(value=>`<small>${value}</small>`).join('')}</span>`;
}
