  if(['vegetation_cover','field_zonal_statistics'].includes(app?.id)&&parameters.source_ref&&!app.method?.raster_sources?.[parameters.source_ref])return {blocked:true,message:'所选原生成果当前不可用，请重新选择已完成且版本可核验的输入成果。'};
