  if(field.type==='select')return `<label class="ap-field">${esc(field.label)}<select data-app-parameter="${esc(field.key)}" ${field.key==='operator'&&(parameters.threshold===undefined||parameters.threshold===null||parameters.threshold==='')?'disabled':''}>${(field.options||[]).map(option=>{const profile=field.key==='source_id'?(app.method?.index_profiles?.[index]?.[option.value]||app.method?.source_profiles?.[option.value]):null,unavailable=option.available===false||profile?.available===false||profile?.supported===false||(app.id==='field_zonal_statistics'&&field.key==='field'&&option.value!=='auto'&&!this.rasterSource(app,draft)?.supported_fields?.includes(option.value))||(field.key==='source_id'&&index==='ndre'&&option.value==='pc_landsat_c2_l2');return `<option value="${esc(option.value)}" ${String(value??'')===String(option.value)?'selected':''} ${unavailable?'disabled':''}>${esc(field.key==='index_id'?option.label.replace(/\s*·\s*\d+(?:\/\d+)?m参考/,''):option.label)}${unavailable?'（不适用）':''}</option>`}).join('')}</select>${field.help?`<small>${esc(field.help)}</small>`:''}</label>`;
  if(field.type==='text')return `<label class="ap-field">${esc(field.label)}<input data-app-parameter="${esc(field.key)}" type="text" maxlength="30" value="${esc(value??'')}" placeholder="例如：天门市">${field.help?`<small>${esc(field.help)}</small>`:''}</label>`;
